	protected static class CacheKey : Comparable<CacheKey> {
		// TODO: Should key on platform, not trace
		protected Trace trace;
		protected TracePlatform platform;
		protected TraceSchedule time;
		private int hashCode;

		public CacheKey(TracePlatform platform, TraceSchedule time) {
			this.platform = Objects.requireNonNull(platform);
			this.trace = platform.getTrace();
			this.time = Objects.requireNonNull(time);
			this.hashCode = Objects.hash(trace, time);
		}

		/* @Override */
		public int hashCode() {
			return hashCode;
		}

		/* @Override */
		public bool equals(object obj) {
			if (!(obj is CacheKey)) {
				return false;
			}
			CacheKey that = (CacheKey) obj;
			if (this.trace != that.trace) {
				return false;
			}
			if (!Objects.equals(this.time, that.time)) {
				return false;
			}
			return true;
		}

		/* @Override */
		public int compareTo(CacheKey that) {
			return compareKey(that).compareTo;
		}

		public CompareResult compareKey(CacheKey that) {
			CompareResult result;

			// I don't care the order, I just care that traces matter first
			result = CompareResult.unrelated(Integer.compare(System.identityHashCode(this.trace),
				System.identityHashCode(that.trace)));
			if (result != CompareResult.EQUALS) {
				return result;
			}

			result = this.time.compareSchedule(that.time);
			if (result != CompareResult.EQUALS) {
				return result;
			}

			return CompareResult.EQUALS;
		}
	}

	protected abstract class AbstractEmulateTask<T> : Task {
		protected CompletableFuture<T> future = new();

		public AbstractEmulateTask(string title, bool hasProgress) : base(title, true, hasProgress, false, false)
    {
		}

		protected abstract T compute(TaskMonitor monitor);

		/* @Override */
		public void run(TaskMonitor monitor)
    {
			try {
				future.complete(compute(monitor));
			}
			catch (CancelledException e) {
				future.completeExceptionally(e);
				throw e;
			}
			catch (Throwable e) {
				future.completeExceptionally(e);
				ExceptionUtils.rethrow(e);
			}
		}
	}

	protected class EmulateTask : AbstractEmulateTask<Long> {
		protected CacheKey key;

		public EmulateTask(CacheKey key) : base("Emulate " + key.time + " in " + key.trace, true)
    {
			this.key = key;
		}

		/* @Override */
		protected Long compute(TaskMonitor monitor)
    {
			return doEmulate(key, monitor);
		}
	}

	protected class RunEmulatorTask : AbstractEmulateTask<EmulationResult> {
		private CacheKey from;
		private Scheduler scheduler;

		public RunEmulatorTask(CacheKey from, Scheduler scheduler) : base("Emulating...", false)
    {
			this.from = from;
			this.scheduler = scheduler;
		}

		/* @Override */
		protected EmulationResult compute(TaskMonitor monitor)
    {
			EmulationResult result = doRun(from, monitor, scheduler);
			if (result.error() is InjectionErrorPcodeExecutionException) {
				Msg.showError(this, null, "Breakpoint Emulation Error",
					"Compilation error in user-provided breakpoint Sleigh code.");
			}
			return result;
		}
	}

