	class BusyEmu : AutoCloseable {
		private CachedEmulator ce;

		private BusyEmu(CachedEmulator ce) {
			this.ce = ce;
			bool fire = false;
			lock (busy) {
				Integer count = busy.get(ce);
				if (count == null) {
					busy.put(ce, 1);
					fire = true;
				}
				else {
					busy.put(ce, count + 1);
				}
			}
			if (fire) {
				stateListeners.invoke().running(ce);
			}
		}

		/* @Override */
		public void close() {
			bool fire = false;
			lock (busy) {
				int count = busy.get(ce);
				if (count == 1) {
					busy.remove(ce);
					fire = true;
				}
				else {
					busy.put(ce, count - 1);
				}
			}
			if (fire) {
				stateListeners.invoke().stopped(ce);
			}
		}

		public BusyEmu dup() {
			return new BusyEmu(ce);
		}
	}

